gPS(){return"\u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u0905\u092c \u092e\u093e\u0928\u094d\u092f \u0928\u0939\u0940\u0902 \u0939\u0948"},
PQ(a,b){return a+" \u0928\u0947 \u0911\u0930\u094d\u0921\u0930 \u201c"+b+"\u201d \u0915\u093e \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u0935\u093e\u092a\u0938 \u0932\u0947 \u0932\u093f\u092f\u093e \u0939\u0948\u0964"},
gPR(){return"\u0911\u0930\u094d\u0921\u0930 \u092a\u094d\u0930\u0915\u093e\u0936\u093f\u0924 \u0939\u0948\u0964 \u0915\u094b\u0908 \u0905\u0928\u094d\u092f \u0938\u0915\u094d\u0930\u093f\u092f \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u091a\u0941\u0928\u0947\u0902 \u092f\u093e \u0928\u090f \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935\u094b\u0902 \u0915\u0940 \u092a\u094d\u0930\u0924\u0940\u0915\u094d\u0937\u093e \u0915\u0930\u0947\u0902\u0964"},
gOO(){return"\u0917\u094d\u0930\u093e\u0939\u0915 \u0928\u0947 \u0906\u092a\u0915\u093e \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u0905\u0938\u094d\u0935\u0940\u0915\u093e\u0930 \u0915\u093f\u092f\u093e"},
OM(a){return"\u0911\u0930\u094d\u0921\u0930 \u201c"+a+"\u201d \u0915\u093e \u0906\u092a\u0915\u093e \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u0905\u092c \u0938\u0915\u094d\u0930\u093f\u092f \u0928\u0939\u0940\u0902 \u0939\u0948\u0964"},
gON(){return"\u0915\u094b\u0908 \u092a\u094d\u0930\u0924\u093f\u092c\u0926\u094d\u0927\u0924\u093e \u0928\u0939\u0940\u0902 \u092c\u0928\u0940\u0964 \u092f\u0926\u093f \u0911\u0930\u094d\u0921\u0930 \u0905\u092d\u0940 \u092d\u0940 \u092a\u094d\u0930\u0915\u093e\u0936\u093f\u0924 \u0939\u0948, \u0924\u094b \u0906\u092a \u0928\u092f\u093e \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u092d\u0947\u091c \u0938\u0915\u0924\u0947 \u0939\u0948\u0902; \u090f\u0915 \u0911\u0930\u094d\u0921\u0930 \u0915\u0947 \u0932\u093f\u090f \u0905\u0927\u093f\u0915\u0924\u092e 5 \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u092d\u0947\u091c\u0947 \u091c\u093e \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964"},
gOA(){return"\u0911\u0930\u094d\u0921\u0930 \u0915\u093f\u0938\u0940 \u0905\u0928\u094d\u092f \u0938\u0947\u0935\u093e \u092a\u094d\u0930\u0926\u093e\u0924\u093e \u0915\u094b \u092e\u093f\u0932\u093e"},
Oy(a){return"\u0915\u093f\u0938\u0940 \u0905\u0928\u094d\u092f \u0938\u0947\u0935\u093e \u092a\u094d\u0930\u0926\u093e\u0924\u093e \u0928\u0947 \u0911\u0930\u094d\u0921\u0930 \u201c"+a+"\u201d \u0938\u094d\u0935\u0940\u0915\u093e\u0930 \u0915\u093f\u092f\u093e\u0964"},
gOz(){return"\u0906\u092a\u0915\u093e \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u092c\u0902\u0926 \u0939\u094b \u0917\u092f\u093e \u0915\u094d\u092f\u094b\u0902\u0915\u093f \u0911\u0930\u094d\u0921\u0930 \u0905\u092c \u0915\u093f\u0938\u0940 \u0905\u0928\u094d\u092f \u0938\u0947\u0935\u093e \u092a\u094d\u0930\u0926\u093e\u0924\u093e \u0915\u0947 \u0938\u093e\u0925 \u092a\u094d\u0930\u0917\u0924\u093f \u092e\u0947\u0902 \u0939\u0948\u0964"},
gIP(){return"\u0905\u092c \u0938\u0947\u0935\u093e \u092a\u094d\u0930\u0926\u093e\u0924\u093e \u0915\u0940 \u092a\u0941\u0937\u094d\u091f\u093f \u0915\u0940 \u092a\u094d\u0930\u0924\u0940\u0915\u094d\u0937\u093e \u0915\u0930\u0947\u0902"},
gIN(){return"\u0911\u0930\u094d\u0921\u0930 \u0905\u092d\u0940 \u092a\u094d\u0930\u0917\u0924\u093f \u092e\u0947\u0902 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964 \u0938\u0947\u0935\u093e \u092a\u094d\u0930\u0926\u093e\u0924\u093e \u0915\u094b \u092a\u0939\u0932\u0947 \u0905\u092a\u0928\u0947 \u0926\u093f\u090f \u0939\u0941\u090f \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u0915\u0940 \u0936\u0930\u094d\u0924\u094b\u0902 \u092a\u0930 \u0907\u0938\u0947 \u0938\u094d\u0935\u0940\u0915\u093e\u0930 \u0915\u0930\u0928\u093e \u0939\u094b\u0917\u093e\u0964"},
gIO(){return"\u0938\u0947\u0935\u093e \u092a\u094d\u0930\u0926\u093e\u0924\u093e \u0926\u0942\u0938\u0930\u0947 \u0911\u0930\u094d\u0921\u0930\u094b\u0902 \u092e\u0947\u0902 \u0935\u094d\u092f\u0938\u094d\u0924 \u0939\u094b \u0938\u0915\u0924\u093e \u0939\u0948, \u0907\u0938\u0932\u093f\u090f \u0909\u0924\u094d\u0924\u0930 \u092e\u0947\u0902 \u092e\u093f\u0928\u091f, \u0918\u0902\u091f\u0947 \u092f\u093e \u0915\u0908 \u0926\u093f\u0928 \u0932\u0917 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902; \u0907\u0938\u0915\u093e \u0905\u0930\u094d\u0925 \u092f\u0939 \u0928\u0939\u0940\u0902 \u0915\u093f \u0909\u0938\u0947 \u0906\u092a\u0915\u093e \u0911\u0930\u094d\u0921\u0930 \u092a\u0938\u0902\u0926 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964 \u092f\u0926\u093f \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u0906\u092a\u0915\u094b \u0905\u091a\u094d\u091b\u093e \u0932\u0917\u0947, \u0924\u094b \u0938\u094b\u091a-\u0938\u092e\u091d\u0915\u0930 \u0909\u0924\u094d\u0924\u0930 \u0926\u0947\u0928\u0947 \u0915\u093e \u0938\u092e\u092f \u0926\u0947\u0902\u0964 \u092a\u094d\u0930\u0924\u0940\u0915\u094d\u0937\u093e \u0915\u0947 \u0926\u094c\u0930\u093e\u0928 \u0906\u092a \u0926\u0942\u0938\u0930\u093e \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u0928\u0939\u0940\u0902 \u091a\u0941\u0928 \u0938\u0915\u0924\u0947\u0964 \u091c\u093c\u0930\u0942\u0930\u0924 \u0939\u094b\u0928\u0947 \u092a\u0930 \u0930\u0926\u094d\u0926 \u0915\u0930\u0928\u0947 \u0915\u093e \u0935\u093f\u0915\u0932\u094d\u092a \u0911\u0930\u094d\u0921\u0930 \u092e\u0947\u0902 \u091a\u0941\u0928\u0947 \u0917\u090f \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u092a\u0930 \u092e\u093f\u0932\u0947\u0917\u093e\u0964"},
