gNm(){return"\u0421\u0440\u043e\u043a \u043f\u0440\u043e\u0434\u043b\u0435\u043d\u0438\u044f"},
gNl(){return"\u041f\u0440\u043e\u0434\u043b\u0438\u0442\u044c"},
